// Seed generator (02-TRD §4.6; 05-SCHEMA §11). No DB connection. Deterministic output.
// Usage: node db/tools/gen-seeds.ts [--root <dir>] [--check]
//   writes db/seeds/002_core__g_system_actors.sql (db/meta/system-actors.yaml)
//          db/seeds/010_core__synthetic_tenants.sql (@lims/test-fixtures tenants + actors; roles + grants from permissions.yaml)
//   --check writes nothing; exit 1 naming every stale seed. 003 is written by gen-access-actions (T0B-04), not here.
// 001 is generated by tools/codegen (C0-0C, pnpm codegen), not here; see .orchestra/cr/T0B-09-001-generator.md.
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { join } from "node:path";
import { readYaml, rootDir } from "./sql-lib.ts";
import { tenants } from "../../packages/test-fixtures/src/tenants/index.ts";
import { actors, DEFAULT_ROLES } from "../../packages/test-fixtures/src/actors/index.ts";

const root = rootDir();
const { parse } = createRequire(join(root, "contracts/package.json"))("yaml");
const perms = parse(readFileSync(join(root, "contracts/permissions.yaml"), "utf8"));
const systemActors: Record<string, string> = readYaml(join(root, "db/meta/system-actors.yaml")).system_actors;
const CORE_ACTOR = systemActors.core;
const q = (v: unknown): string => (v === null || v === undefined ? "NULL" : `'${String(v).replace(/'/g, "''")}'`);
const human = (code: string): string => code.charAt(0).toUpperCase() + code.slice(1).replace(/_/g, " ");
const rows = (r: string[]): string => r.map((x) => `  (${x})`).join(",\n");
const LOCKED_AT = "2026-11-07 00:00:00+00"; // [CONV] fixed timestamp: seeds must be deterministic for the idempotent re-run test
// [CONV] insert-only link tables get the same fixed created_at, so a healed (re-inserted) row is identical to the original, not now()
const AT = `${q(LOCKED_AT)}::timestamptz`;

const tenantRoles: { code: string; mfa_required: boolean; description: string }[] = perms.roles;
const roleCodes = tenantRoles.map((r) => r.code);
if (roleCodes.join() !== [...DEFAULT_ROLES].join()) throw new Error("gen-seeds: permissions.yaml roles differ from @lims/test-fixtures DEFAULT_ROLES");

function seed002(): string {
  return [
    "-- GENERATED by db/tools/gen-seeds.ts from db/meta/system-actors.yaml - do not edit by hand (02-TRD §4.1, §4.6; 05-SCHEMA §11).",
    "-- Class G, all environments (prod subset). Fixed UUIDv7s, never changed. Idempotent: re-running inserts nothing new.",
    "SET LOCAL ROLE lims_owner;",
    "",
    "INSERT INTO core.g_system_actors (module, actor_id) VALUES",
    rows(Object.entries(systemActors).map(([m, id]) => `${q(m)}, ${q(id)}`)),
    "ON CONFLICT DO NOTHING;",
    "",
  ].join("\n");
}

// [CONV] id families (IC §1 family, as tenants/actors): role <nibble>4<nn>, membership <nibble>5<nn>; user id = actor id.
const famId = (actorOrTenantId: string, fam: string, nn: string): string => actorOrTenantId.slice(0, -4) + actorOrTenantId.slice(-4, -3) + fam + nn;

function tenantBlock(key: "tenant_a" | "tenant_b"): string[] {
  const t = tenants[key];
  const by = q(CORE_ACTOR);
  const roleId = (code: string): string => famId(t.id, "4", roleCodes.indexOf(code).toString(16).padStart(2, "0"));
  const mine = actors.filter((a) => a.tenantId === t.id && ["user", "partner", "patient"].includes(a.actorType));
  const membershipId = (actorId: string): string => famId(actorId, "5", actorId.slice(-2));
  const grants: string[] = [];
  for (const p of perms.permissions) for (const r of p.roles ?? []) if (roleCodes.includes(r)) grants.push(`${q(t.id)}, ${q(roleId(r))}, ${q(p.code)}, ${by}, ${AT}`);
  const claims = JSON.stringify({ tenant_id: t.id, sub: CORE_ACTOR, actor_type: "system" });
  const scoped = mine.filter((a) => a.centreIds);
  return [
    `-- ---------- ${key}: claims of the core system actor for this tenant (RLS WITH CHECK applies; audit rows carry the actor) ----------`,
    `SELECT set_config('request.jwt.claims', ${q(claims)}, true);`,
    "SET LOCAL ROLE lims_app; -- LD-30: after claims, so the real <table>__insert__tenant WITH CHECK applies (no owner bypass)",
    "",
    "INSERT INTO core.tenants (id, tenant_code, legal_name, display_name, status, created_by, updated_by) VALUES",
    rows([`${q(t.id)}, ${q(key)}, ${q(t.name)}, ${q(t.name)}, 'active', ${by}, ${by}`]),
    "ON CONFLICT DO NOTHING;",
    "",
    "INSERT INTO core.branches (id, tenant_id, branch_code, name, created_by, updated_by) VALUES",
    rows(t.branches.map((b, i) => `${q(b.id)}, ${q(t.id)}, ${q(`${key.slice(-1).toUpperCase()}-B${i + 1}`)}, ${q(b.name)}, ${by}, ${by}`)),
    "ON CONFLICT DO NOTHING;",
    "",
    // [CONV] centre 1 + home collection under branch 1, centre 2 under branch 2
    "INSERT INTO core.collection_centres (id, tenant_id, branch_id, centre_code, name, centre_kind, created_by, updated_by) VALUES",
    rows(t.centres.map((c, i) => `${q(c.id)}, ${q(t.id)}, ${q(t.branches[i === 1 ? 1 : 0]!.id)}, ${q(c.centre_code)}, ${q(c.name)}, ${q(c.centre_kind)}, ${by}, ${by}`)),
    "ON CONFLICT DO NOTHING;",
    "",
    "INSERT INTO core.roles (id, tenant_id, role_code, display_name, description, is_system_default, mfa_required, created_by, updated_by) VALUES",
    rows(tenantRoles.map((r) => `${q(roleId(r.code))}, ${q(t.id)}, ${q(r.code)}, ${q(human(r.code))}, ${q(r.description)}, true, ${r.mfa_required}, ${by}, ${by}`)),
    "ON CONFLICT DO NOTHING;",
    "",
    "INSERT INTO core.role_permissions (tenant_id, role_id, permission_code, created_by, created_at) VALUES",
    rows(grants),
    "ON CONFLICT DO NOTHING;",
    "",
    "INSERT INTO core.users (tenant_id, id, display_name, created_by, updated_by) VALUES",
    rows(mine.map((a) => `${q(t.id)}, ${q(a.id)}, ${q(`${t.name} ${human(a.key.split(".")[1]!)} (SYNTHETIC)`)}, ${by}, ${by}`)),
    "ON CONFLICT DO NOTHING;",
    "",
    "INSERT INTO core.memberships (id, tenant_id, user_id, actor_type, all_centres, status, locked_at, locked_by, lock_reason_code, partner_role, created_by, updated_by) VALUES",
    rows(mine.map((a) => [q(membershipId(a.id)), q(t.id), q(a.id), q(a.actorType), String(a.actorType === "user" && !a.centreIds), "'active'",
      a.locked ? `${q(LOCKED_AT)}::timestamptz` : "NULL", a.locked ? by : "NULL", a.locked ? "'other'" : "NULL", q(a.partnerRole), by, by].join(", "))),
    "ON CONFLICT DO NOTHING;",
    "",
    "INSERT INTO core.membership_roles (tenant_id, membership_id, role_id, created_by, created_at) VALUES",
    rows(mine.filter((a) => a.role).map((a) => `${q(t.id)}, ${q(membershipId(a.id))}, ${q(roleId(a.role!))}, ${by}, ${AT}`)),
    "ON CONFLICT DO NOTHING;",
    "",
    "INSERT INTO core.membership_centres (tenant_id, membership_id, centre_id, created_by, created_at) VALUES",
    rows(scoped.flatMap((a) => a.centreIds!.map((c) => `${q(t.id)}, ${q(membershipId(a.id))}, ${q(c)}, ${by}, ${AT}`))),
    "ON CONFLICT DO NOTHING;",
    "",
  ];
}

function seed010(): string {
  return [
    "-- GENERATED by db/tools/gen-seeds.ts from @lims/test-fixtures (tenants, actors) + contracts/permissions.yaml - do not edit by hand.",
    "-- 02-TRD §3.5, §4.6; 05-SCHEMA §11. SYNTHETIC ONLY: dev, ci, staging; never production (REQ-SEC-041, REQ-SEC-136).",
    "-- Portal-link, bridge_agent, queue_display and system actors have no membership (claims come from their resolvers).",
    "-- memberships.is_active is GENERATED (08 A3.4): rows set status only. Idempotent: re-running inserts nothing new.",
    ...tenantBlock("tenant_a"),
    ...tenantBlock("tenant_b"),
    "SELECT set_config('request.jwt.claims', '', true);",
    "",
  ].join("\n");
}

const out: [string, string][] = [
  ["db/seeds/002_core__g_system_actors.sql", seed002()],
  ["db/seeds/010_core__synthetic_tenants.sql", seed010()],
];
if (process.argv.includes("--check")) {
  const stale = out.filter(([p, s]) => { try { return readFileSync(join(root, p), "utf8").replace(/\r\n/g, "\n") !== s; } catch { return true; } });
  for (const [p] of stale) console.error(`gen-seeds: stale ${p}`);
  process.exit(stale.length ? 1 : 0);
}
for (const [p, s] of out) writeFileSync(join(root, p), s);
